from pathlib import Path

page = Path('app/classifieds/page.tsx')
text = page.read_text()

old = '''{portalRole === "professional" && <section className="relative h-full min-h-[250px] min-w-0 overflow-hidden rounded-2xl border-2 border-[#01A32E]/55 bg-[#effaf2] p-4 shadow-md sm:p-5"><div className="absolute inset-y-0 left-0 w-1.5 bg-[#01A32E]" /><div className="flex items-end justify-between gap-3"><div><p className="text-xs font-black uppercase tracking-[0.12em] text-[#017f27]">My availability ads</p><h2 className="mt-1 text-xl font-black text-[#002757]">My DentalJobs</h2><p className="mt-1 text-sm text-slate-500">Manage your active and previous Looking for an Office ads.</p></div><span className="rounded-full border border-[#01A32E]/30 bg-white px-3 py-1.5 text-xs font-black text-[#017f27] shadow-sm">{myProfessionalJobs.length} posting{myProfessionalJobs.length === 1 ? "" : "s"}</span></div>{manageError && <p className="mt-3 rounded-xl bg-rose-50 p-3 text-sm font-bold text-rose-700">{manageError}</p>}<div className="mt-4 grid gap-3">{myProfessionalJobs.length === 0 ? <div className="rounded-xl border border-dashed border-[#4285F4]/40 bg-white p-5 text-sm font-semibold text-slate-500">You have no Looking for an Office postings yet.</div> : myProfessionalJobs.map((job) => { const daysLeft = Math.max(0, Math.ceil((new Date(job.expires_at).getTime() - Date.now()) / 86400000)); const isActive = job.status === "active" && daysLeft > 0; const displayStatus = job.status === "active" && daysLeft === 0 ? "expired" : job.status; const theme = getProfessionalCardTheme(job.profession); return <article key={job.id} className="min-h-[118px] rounded-xl border-2 bg-white p-3 shadow-sm" style={{ borderColor: theme.border }}><div className="flex flex-col gap-2"><div><div className="flex flex-wrap items-center gap-1.5"><span className={`rounded-full px-2 py-0.5 text-[10px] font-black uppercase ${isActive ? "bg-[#eaf8ee] text-[#017f27]" : displayStatus === "paused" ? "bg-amber-50 text-amber-700" : displayStatus === "filled" ? "bg-blue-50 text-blue-700" : "bg-slate-100 text-slate-600"}`}>{displayStatus === "filled" ? "found office" : displayStatus}</span>{isActive && <span className="text-[11px] font-bold text-slate-400">{daysLeft} day{daysLeft === 1 ? "" : "s"} remaining</span>}</div><h3 className="mt-1.5 text-sm font-black leading-tight" style={{ color: theme.text }}>{job.profession} — {job.employment_type}</h3><p className="mt-0.5 text-xs text-slate-500">{job.city}, {job.province}</p><div className="mt-2"><ShareListingButton listingId={job.id} compact /></div></div><div className="flex w-full justify-end">
          <button type="button" onClick={() => setProfessionalManageListing(job)} className="inline-flex items-center justify-center gap-1 rounded-md bg-[#002757] px-2.5 py-1 text-[10px] font-black text-white shadow-sm transition hover:bg-[#01A32E]"><MoreVertical size={12}/> Manage</button>
        </div></div></article>})}</div></section>}'''

new = '''{portalRole === "professional" && <section className="relative h-full min-h-[250px] min-w-0 overflow-hidden rounded-2xl border-2 border-[#01A32E]/55 bg-[#effaf2] p-4 shadow-md sm:p-5"><div className="absolute inset-y-0 left-0 w-1.5 bg-[#01A32E]" /><div className="flex items-end justify-between gap-3"><div><p className="text-xs font-black uppercase tracking-[0.12em] text-[#017f27]">My availability ads</p><h2 className="mt-1 text-xl font-black text-[#002757]">My DentalJobs</h2><p className="mt-1 text-sm text-slate-500">Manage your active and previous Looking for an Office ads.</p></div><span className="rounded-full border border-[#01A32E]/30 bg-white px-3 py-1.5 text-xs font-black text-[#017f27] shadow-sm">{myProfessionalJobs.length} posting{myProfessionalJobs.length === 1 ? "" : "s"}</span></div>{manageError && <p className="mt-3 rounded-xl bg-rose-50 p-3 text-sm font-bold text-rose-700">{manageError}</p>}<div className="mt-4 grid gap-3">{myProfessionalJobs.length === 0 ? <div className="rounded-xl border border-dashed border-[#4285F4]/40 bg-white p-5 text-sm font-semibold text-slate-500">You have no Looking for an Office postings yet.</div> : myProfessionalJobs.map((job) => { const daysLeft = Math.max(0, Math.ceil((new Date(job.expires_at).getTime() - Date.now()) / 86400000)); const isActive = job.status === "active" && daysLeft > 0; const displayStatus = job.status === "active" && daysLeft === 0 ? "expired" : job.status; const theme = getProfessionalCardTheme(job.profession); return <article key={job.id} className="rounded-2xl border-2 bg-white p-4 shadow-sm" style={{ borderColor: theme.border }}><div><div className="flex flex-wrap items-center gap-1.5"><span className={`rounded-full px-2 py-0.5 text-[10px] font-black uppercase ${isActive ? "bg-[#eaf8ee] text-[#017f27]" : displayStatus === "paused" ? "bg-amber-50 text-amber-700" : displayStatus === "filled" ? "bg-blue-50 text-blue-700" : "bg-slate-100 text-slate-600"}`}>{displayStatus === "filled" ? "found office" : displayStatus}</span>{isActive && <span className="text-[11px] font-bold text-slate-400">{daysLeft} day{daysLeft === 1 ? "" : "s"} remaining</span>}</div><h3 className="mt-2 text-base font-black leading-tight" style={{ color: theme.text }}>{job.profession} — {job.employment_type}</h3><p className="mt-1 text-sm font-semibold text-slate-500">{job.city}, {job.province}</p></div><div className="mt-4 flex w-full flex-wrap items-center gap-2.5 border-t border-slate-100 pt-4"><button type="button" onClick={() => setProfessionalManageListing(job)} className="inline-flex min-h-10 items-center justify-center gap-2 rounded-xl bg-[#002757] px-4 py-2.5 text-sm font-black text-white shadow-sm transition hover:bg-[#01A32E]"><MoreVertical size={15}/> Manage</button><Link href={`/jobs/${job.id}?returnTo=${encodeURIComponent("/dental-jobs")}`} className="inline-flex min-h-10 items-center justify-center gap-2 whitespace-nowrap rounded-xl border-2 border-[#4285F4]/45 bg-white px-4 py-2.5 text-sm font-black text-[#245FB8] shadow-sm transition hover:bg-[#eef4ff]"><FileText size={15}/> View Ad</Link><div className="relative z-20 inline-flex shrink-0"><ShareListingButton listingId={job.id} compact /></div></div></article>})}</div></section>}'''

if old not in text:
    raise SystemExit('Professional availability ad card anchor not found')

text = text.replace(old, new, 1)
page.write_text(text)
print('Updated professional availability ad cards with visible Manage, View Ad, and Share Listing actions')
